import { useState, useEffect } from "react";
import axios from "axios";

export default function EditCriterionModal({ criterion, isOpen, onClose, onUpdate }) {
  const [formData, setFormData] = useState({
    name: "",
    cases: [],
  });

  useEffect(() => {
    if (criterion) {
      setFormData({
        name: criterion.name,
        cases: criterion.cases.map((c) => ({
          description: c.description,
          points: c.points,
        })),
      });
    }
  }, [criterion]);

  const handleChange = (e, index) => {
    const { name, value } = e.target;
    if (name === "name") {
      setFormData((prev) => ({ ...prev, [name]: value }));
    } else {
      const updatedCases = formData.cases.map((c, i) =>
        i === index ? { ...c, [name]: name === "points" ? parseInt(value) || 0 : value } : c
      );
      setFormData((prev) => ({ ...prev, cases: updatedCases }));
    }
  };

  const handleAddCase = () => {
    setFormData((prev) => ({
      ...prev,
      cases: [...prev.cases, { description: "", points: 0 }],
    }));
  };

  const handleRemoveCase = (index) => {
    setFormData((prev) => ({
      ...prev,
      cases: prev.cases.filter((_, i) => i !== index),
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      let response;
      if (criterion._id === "new") {
        // Create new criterion
        response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/criteria`,
          formData,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );
      } else {
        // Update existing criterion
        response = await axios.put(
          `${process.env.REACT_APP_API_URL}/api/criteria/${criterion._id}`,
          formData,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );
      }
      onUpdate(response.data);
      onClose();
    } catch (error) {
      console.error("Failed to save criterion:", error);
    }
  };

  if (!isOpen || !criterion) return null;

  return (
    <>
      <div className="fixed inset-0 bg-black/50 z-50" onClick={onClose} />
      <div className="fixed left-1/2 top-1/2 z-50 max-h-[90vh] w-[90vw] max-w-[600px] -translate-x-1/2 -translate-y-1/2 rounded-lg bg-white p-6 shadow-lg overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold">{criterion._id === "new" ? "Create Criterion" : "Edit Criterion"}</h2>
          <button onClick={onClose} className="rounded-full p-1 hover:bg-gray-100">
            <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Name</label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={(e) => handleChange(e)}
              className="mt-1 block w-full rounded-md border border-gray-300 p-2"
              required
            />
          </div>

          <div className="space-y-4">
            {formData.cases.map((c, index) => (
              <div key={index} className="grid grid-cols-2 gap-4 items-end">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Case Description</label>
                  <input
                    type="text"
                    name="description"
                    value={c.description}
                    onChange={(e) => handleChange(e, index)}
                    className="mt-1 block w-full rounded-md border border-gray-300 p-2"
                    required
                  />
                </div>
                <div className="flex items-center gap-2">
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700">Points</label>
                    <input
                      type="number"
                      name="points"
                      value={c.points}
                      onChange={(e) => handleChange(e, index)}
                      className="mt-1 block w-full rounded-md border border-gray-300 p-2"
                      required
                    />
                  </div>
                  <button
                    type="button"
                    onClick={() => handleRemoveCase(index)}
                    className="p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors"
                  >
                    <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              </div>
            ))}
            <button
              type="button"
              onClick={handleAddCase}
              className="mt-2 px-4 py-2 text-sm font-medium text-teal-600 border border-teal-600 rounded-md hover:bg-teal-50"
            >
              Add Case
            </button>
          </div>

          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-md hover:bg-gray-200"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-sm font-medium text-white bg-teal-600 rounded-md hover:bg-teal-700"
            >
              {criterion._id === "new" ? "Create" : "Save Changes"}
            </button>
          </div>
        </form>
      </div>
    </>
  );
}
